import {exchangeAction,exchangeState,watchExchange,refreshExchange} from './exchange-client.mjs';
import {presenceLabel} from './chat-model.mjs';
const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e};
const launch=make('button',null,'message-launcher'),badge=make('span',null,'message-notification');launch.type='button';launch.append(make('span','Messages'),badge);launch.setAttribute('aria-controls','message-panel');launch.setAttribute('aria-expanded','false');
const panel=make('section',null,'message-panel');panel.id='message-panel';panel.hidden=true;panel.setAttribute('role','region');panel.setAttribute('aria-label','Messages');const header=make('header',null,'message-head'),back=make('button','‹','btn secondary'),title=make('h2','Messages'),actions=make('div',null,'row'),min=make('button','−','btn secondary'),close=make('button','×','btn secondary'),body=make('div',null,'message-body'),notice=make('p',null,'message-error'),footer=make('footer','Messages are deleted after 7 days.','message-footer');for(const [b,label] of [[back,'Back to conversations'],[min,'Minimize messages'],[close,'Close messages']]){b.type='button';b.setAttribute('aria-label',label)}actions.append(min,close);header.append(back,title,actions);panel.append(header,notice,body,footer);document.body.append(launch,panel);
let current=null,thread=null,loading=false,mutating=false,viewToken=0,actorId=null;const drafts=new Map();
function dot(online){const e=make('span',null,'presence-dot '+(online?'online':'offline'));e.setAttribute('role','img');e.setAttribute('aria-label',online?'Online':'Offline');return e}
function toggle(open){panel.hidden=!open;launch.hidden=open;launch.setAttribute('aria-expanded',String(open));if(open)close.focus();else launch.focus()}
function inbox(){current=null;thread=null;viewToken++;back.hidden=true;title.textContent='Messages';notice.textContent='';body.replaceChildren();const state=exchangeState();if(!state.actor){body.append(make('p','Log in to send messages.','caption'));return}if(state.error){notice.textContent=state.error;return}for(const c of state.inbox){const button=make('button',null,'message-conversation'+(c.unread?' unread':'')),line=make('span',null,'message-person');button.type='button';line.append(dot(c.online),make('strong',c.name));if(c.unread)line.append(make('span','New','unread-label'));button.append(line,make('span',c.blocked?'Blocked':c.messages.at(-1)?.text||'No messages','caption'));button.onclick=()=>open(c);body.append(button)}if(!state.inbox.length)body.append(make('h3','No conversations'),make('p','Choose Chat beside a player to start.','caption'))}
async function mutate(action,payload,after){if(mutating)return;mutating=true;body.querySelectorAll('button').forEach(b=>b.disabled=true);notice.textContent='';const id=current?.id;try{await exchangeAction(action,payload);await refreshExchange();if(current?.id===id)await after?.()}catch(e){notice.textContent=e.message}finally{mutating=false;if(current?.id===id&&current&&thread)renderThread();else if(!current)inbox()}}
function renderThread(){if(!current||!thread)return;const c=current;title.replaceChildren(dot(c.online),document.createTextNode(c.name));back.hidden=false;body.replaceChildren(make('p',presenceLabel(c.online,c.lastSeen||c.last_seen),'caption'));const tools=make('div',null,'message-chat-tools'),del=make('button','Delete chat','btn secondary'),block=make('button',thread.blocked_by_me?'Unblock':'Block','btn secondary');del.type=block.type='button';del.onclick=()=>mutate('delete',{peer:c.id},()=>{drafts.delete(c.id);inbox()});block.onclick=()=>mutate(thread.blocked_by_me?'unblock':'block',{peer:c.id},async()=>{await loadThread(true)});tools.append(del,block);body.append(tools);const list=make('div',null,'message-thread');for(const m of thread.messages){const bubble=make('div',null,'message-bubble'+(m.mine?' mine':''));bubble.append(make('p',m.text),make('small',m.mine?(m.read?'Read':'Sent'):new Date(m.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})));list.append(bubble)}if(!thread.messages.length)list.append(make('p','No messages yet.','caption'));body.append(list);if(thread.blocked){body.append(make('p',thread.blocked_by_me?'This person is blocked. Unblock to chat again.':'Messaging with this player is unavailable.','notice'));return}const form=make('form',null,'message-compose'),input=make('textarea'),send=make('button','Send','btn');input.setAttribute('aria-label','Message');input.placeholder='Write a message…';input.rows=2;input.maxLength=1000;input.value=drafts.get(c.id)||'';input.oninput=()=>drafts.set(c.id,input.value);send.type='submit';send.disabled=mutating;form.append(input,send);form.onsubmit=e=>{e.preventDefault();const text=input.value.trim();if(!text)return;mutate('send',{peer:c.id,text},async()=>{drafts.delete(c.id);await loadThread(true)})};body.append(form)}
async function loadThread(force=false){if(!current||loading||document.hidden||panel.hidden)return;loading=true;const id=current.id,token=viewToken;try{const next=await exchangeAction('thread',{peer:id});if(token!==viewToken||current?.id!==id)return;const signature=JSON.stringify(next);if(force||signature!==JSON.stringify(thread)){const typing=body.querySelector('textarea')===document.activeElement;const caret=typing?document.activeElement.selectionStart:null;thread=next;const scroll=body.scrollTop,atBottom=body.scrollHeight-body.clientHeight-scroll<100;renderThread();body.scrollTop=atBottom?body.scrollHeight:scroll;if(typing){const input=body.querySelector('textarea');input?.focus();if(input&&caret!==null)input.setSelectionRange(caret,caret)}}}catch(e){if(token===viewToken)notice.textContent=e.message}finally{loading=false}}
async function open(person){if(!exchangeState().actor){inbox();toggle(true);return}viewToken++;current=person;thread=null;body.replaceChildren(make('p','Loading messages…','caption'));toggle(true);await loadThread(true);await refreshExchange()}
launch.onclick=()=>{inbox();toggle(true);refreshExchange()};back.onclick=inbox;min.onclick=close.onclick=()=>toggle(false);panel.addEventListener('keydown',e=>{if(e.key==='Escape')toggle(false)});
watchExchange(state=>{if(actorId!==state.actor?.id){actorId=state.actor?.id;drafts.clear();current=null;thread=null;viewToken++;if(!panel.hidden)inbox()}const unread=state.inbox.filter(c=>c.unread).length;badge.hidden=!unread;badge.textContent=String(unread);launch.setAttribute('aria-label',unread?'Open messages, '+unread+' unread chats':'Open messages');if(state.error&&!panel.hidden)notice.textContent=state.error;if(!panel.hidden&&!current)inbox();if(current){const peer=state.inbox.find(c=>c.id===current.id);if(peer)current={...current,...peer}}});
window.addEventListener('card-chat-open',e=>{open(e.detail)});const timer=setInterval(()=>{if(!panel.hidden&&current&&!mutating)loadThread()},5000);window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});inbox();
